import unittest

from hourglass.rounding import round_labels, round_span
from hourglass.models import Span


class RoundSpanTests(unittest.TestCase):
    def test_nearest_step(self):
        result = round_span(Span(541, 1023), 15)
        self.assertEqual(result, Span(540, 1020))

    def test_halves_round_up(self):
        result = round_span(Span(68, 128), 15)
        self.assertEqual(result, Span(75, 135))

    def test_collapsed_span_is_rejected(self):
        with self.assertRaises(ValueError):
            round_span(Span(540, 544), 15)

    def test_end_of_day_is_kept(self):
        result = round_span(Span(1400, 1440), 30)
        self.assertEqual(result, Span(1410, 1440))


class RoundLabelsTests(unittest.TestCase):
    def test_label_format(self):
        spans = [Span(540, 1035)]
        self.assertEqual(
            round_labels(spans, 15),
            ["09:00-17:15 (8h 15m)"],
        )

    def test_rounds_before_labelling(self):
        spans = [Span(542, 1018), Span(1100, 1200)]
        self.assertEqual(
            round_labels(spans, 15),
            ["09:00-17:00 (8h 0m)", "18:15-20:00 (1h 45m)"],
        )

    def test_empty_list(self):
        self.assertEqual(round_labels([], 15), [])

    def test_valid_steps(self):
        for step in (1, 5, 6, 10, 15, 20, 30, 60):
            with self.subTest(step=step):
                round_labels([Span(0, 600)], step)


class BadStepTests(unittest.TestCase):
    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 90, 2.5):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    round_labels([Span(0, 600)], step)

    def test_bad_step_raises_for_empty_list(self):
        with self.assertRaises(ValueError):
            round_labels([], 0)
